CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1 INT COLLATE NOCASE, c2, c3 INTEGER COLLATE NOCASE, c4 TEXT COLLATE NOCASE);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-2.5, 0.1, NULL, 'eta', 2.5);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('zeta', x'ad9fc325', 3, -628, 231);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-39.249, 123456789012, NULL, 'iota', 390.186);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL UNIQUE, c1 TEXT DEFAULT 'd', c2 TEXT DEFAULT 'd', ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(0, 'alpha', 'nu', 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(NULL, 123456789012, 'chi', 1);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 TEXT CHECK(c0 IS NULL OR length(c0) < 40), c1 REAL, c2 VARCHAR(10) UNIQUE, c3 REAL, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES('gamma', NULL, 4, 0, 5);
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', -2, 3), instr('0x1F', '0x1F'), replace('0x1F', 'a', 'XY'), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE 'a%', '0x1F' GLOB '*', char(70, 569), '0x1F' || '0x1F', '0x1F' < '0x1F', '0x1F' = '0x1F' COLLATE NOCASE;
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', 2, 2), instr(' pad ', 'psi'), replace(' pad ', '', '_'), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE '_', ' pad ' GLOB '*', char(69, 260), ' pad ' || 'psi', ' pad ' < 'psi', ' pad ' = 'psi' COLLATE NOCASE;
SELECT length('Ελλάδα'), upper('Ελλάδα'), lower('Ελλάδα'), substr('Ελλάδα', 0, 2), instr('Ελλάδα', 'MU'), replace('Ελλάδα', 'a', 'XY'), trim('Ελλάδα'), ltrim('Ελλάδα', 'ab'), hex('Ελλάδα'), quote('Ελλάδα'), unicode('Ελλάδα'), 'Ελλάδα' LIKE '%a_', 'Ελλάδα' GLOB '*[a-m]*', char(78, 683), 'Ελλάδα' || 'MU', 'Ελλάδα' < 'MU', 'Ελλάδα' = 'MU' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', 4, 5), instr('a%b', 'theta'), replace('a%b', 'e', ''), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '_', 'a%b' GLOB '*', char(65, 224), 'a%b' || 'theta', 'a%b' < 'theta', 'a%b' = 'theta' COLLATE NOCASE;
SELECT length('über'), upper('über'), lower('über'), substr('über', -3, 4), instr('über', 'beta'), replace('über', 'é', ''), trim('über'), ltrim('über', 'ab'), hex('über'), quote('über'), unicode('über'), 'über' LIKE '%', 'über' GLOB '*[a-m]*', char(68, 228), 'über' || 'beta', 'über' < 'beta', 'über' = 'beta' COLLATE NOCASE;
SELECT length('1e3'), upper('1e3'), lower('1e3'), substr('1e3', -1, 5), instr('1e3', 'iota'), replace('1e3', 'a', '_'), trim('1e3'), ltrim('1e3', 'ab'), hex('1e3'), quote('1e3'), unicode('1e3'), '1e3' LIKE '_', '1e3' GLOB '*', char(81, 847), '1e3' || 'iota', '1e3' < 'iota', '1e3' = 'iota' COLLATE NOCASE;
SELECT a.id, b.id, a.c0, b.ref FROM t0 a JOIN t1 b ON b.ref = a.id ORDER BY 1, 2 LIMIT 9;
SELECT count(*) FROM t0 a JOIN t0 b USING(id);
